```javascript
/**
 * Evalúa una fórmula de estilo Excel almacenada como string.
 * Esto incluye funciones básicas (como SUMA) y operaciones aritméticas simples.
 * @param {string} formula - La cadena que contiene la fórmula (ej: "=SUMA(A1:A3)").
 * @returns {number|string} El resultado calculado o el valor original si no se pudo calcular.
 */
function calculateFormula(formula) {
    if (!formula || !formula.startsWith('=')) return formula;

    let cleanedFormula = formula.substring(1).trim(); // Quitar '=' inicial

    // 1. Manejo de SUMA
    const sumMatch = cleanedFormula.match(/SUMA\s*\((.*)\)/i);
    if (sumMatch) {
        const content = sumMatch[1];
        let coordinatesToSum = [];

        // Detectar si es un rango simple (ej: A1:A3) o una lista de celdas/rangos.
        // Si hay ':' asumimos que es un rango primario, sino, asumimos que son elementos separados por ;
        if (content.includes(':')) {
            const ranges = content.split(/;|\s+/).filter(r => r); // Dividir por `;` o espacios si hay múltiples rangos
            ranges.forEach(rangeStr => {
                // Si es un rango simple A1:A3, lo procesamos
                if (rangeStr.includes(':')) {
                    const [startRef, endRef] = rangeStr.split(':');
                    const startCoords = getCoordinateParts(startRef); // ["A", 1]
                    const endCoords = getCoordinateParts(endRef);   // ["A", 3]

                    if (startCoords && endCoords) {
                        for (let r = startCoords[1]; r <= endCoords[1]; r++) {
                            coordinatesToSum.push(getCoordinate(startCoords[0], r));
                        }
                    }
                } else {
                    // Si es un solo elemento suelto, lo añadimos
                    coordinatesToSum.push(rangeStr);
                }
            });
        } else {
             // Lista de celdas o rangos separados por ; (ej: A1;B2)
            const parts = content.split(/;\s*/).filter(p => p);
            parts.forEach(part => {
                if (part.includes(':')) {
                    const [startRef, endRef] = part.split(':');
                    const startCoords = getCoordinateParts(startRef);
                    const endCoords = getCoordinateParts(endRef);

                    if (startCoords && endCoords) {
                        for (let r = startCoords[1]; r <= endCoords[1]; r++) {
                            coordinatesToSum.push(getCoordinate(startCoords[0], r));
                        }
                    }
                } else {
                    // Celda suelta
                    coordinatesToSum.push(part);
                }
            });
        }

        let total = 0;
        for (const coord of coordinatesToSum) {
            const value = estado.data[coord];
            if (value && !isNaN(parseFloat(value))) {
                total += parseFloat(value);
            }
        }
        return total.toString();
    }

    // 2. Manejo de Operaciones Aritméticas Básicas
    try {
        // Expresión regular para encontrar referencias de coordenadas (ej: A1, B2)
        const coordRegex = /([A-Z]+[0-9]+)/g;
        let expression = cleanedFormula;

        // Reemplazar todas las referencias encontradas por sus valores numéricos.
        expression = expression.replace(coordRegex, (match) => {
            const value = estado.data[match];
            return value === undefined ? '0' : parseFloat(value);
        });

        // Evaluar la expresión matemática resultante en JavaScript
        if (!isNaN(parseFloat(expression))) {
             return eval(expression).toString();
        }
    } catch (e) {
        console.warn("Error evaluando fórmula:", e);
    }

    return formula; // Devolver original si falla la evaluación
}

/**
 * Helper interno para parsear una referencia de coordenada en [col, row].
 * @param {string} ref - Referencia como "A1" o "B2".
 * @returns {[string, number] | null} Columna y fila.
 */
function getCoordinateParts(ref) {
    const col = '';
    let i;
    for (i = 0; i < ref.length; i++) {
        const char = ref[i];
        if (isNaN(parseInt(char))) {
            col += char;
        } else {
            break; // El resto son números de fila
        }
    }
    const row = parseInt(ref.substring(i));
    return [col, row];
}
