/**
 * Evalúa una cadena de fórmula matemática usando los valores actuales en el estado global.
 * @param {string} formula - La fórmula sin el signo '=' (ej: "B1+C1").
 * @returns {string|number} El resultado calculado, o la fórmula si falla.
 */
function calculateValue(formula) {
    // Expresión regular para encontrar patrones de coordenadas (Ej: A1, J20).
    // Captura letras y números que simulan coordenadas válidas en el estado.
    const coordinateRegex = /([A-Z]+[1-9]\d*)/g; 
    let expression = formula;
    let match;

    while ((match = coordinateRegex.exec(formula)) !== null) {
        const coordinate = match[1]; // Ej: B1
        // Obtiene el valor del estado para esta coordenada. Usa '0' si no existe.
        // Esto asegura que la evaluación matemática no falle por coordenadas faltantes.
        let value = estado.data[coordinate] || '0'; 

        // Aseguramos que los valores se manejen como números en la expresión, a menos que sean cadenas.
        // Para simplificar y manejar el caso de texto (ej: "Hola"), lo envolvemos en paréntesis.
        expression = expression.replace(match[0], `(${value})`);
    }

    try {
        // Evalúa la expresión matemática resultante.
        const result = eval(expression);
        if (typeof result === 'number') {
            return parseFloat(result.toFixed(2)); // Limitar decimales a 2
        }
        return String(result);
    } catch (e) {
        console.error("Error evaluando fórmula:", e);
        // Si falla la evaluación, devolvemos el error o la fórmula original para inspección.
        return formula; 
    }
}
