            document.body.appendChild(menu); // Añadir al body para posicionamiento absoluto
        }

        // Limpiar contenido anterior y construir el nuevo menú
        menu.innerHTML = '';
        const title = document.createElement('div');
        title.textContent = "Acciones de Celda";
        title.className = 'menu-title';
        menu.appendChild(title);

        const colorHeader = document.createElement('div');
        colorHeader.textContent = "Color de Fondo:";
        colorHeader.className = 'menu-option-group';
        menu.appendChild(colorHeader);


        // Generar opciones de colores comunes (rojo, azul, verde, amarillo)
        const colors = [
            { name: 'Rojo', hex: '#FF0000' }, 
            { name: 'Azul', hex: '#0000FF' }, 
            { name: 'Verde', hex: '#00AA00' }, 
            { name: 'Amarillo', hex: '#FFFF00' }
        ];

        colors.forEach(color => {
            const option = document.createElement('button');
            option.textContent = color.name;
            option.style.backgroundColor = color.hex;
            option.dataset.colorHex = color.hex; // Usamos un atributo data para guardar el valor
            option.className = 'menu-color-option';

            // Manejar la acción de colorear al hacer clic en la opción del menú
            option.addEventListener('click', (e) => {
                const hexColor = e.currentTarget.dataset.colorHex;
                setCellBackgroundColor(target, hexColor); // Llama a la función lógica

                // Ocultar el menú después de usarlo
                menu.style.display = 'none'; 
            });
            menu.appendChild(option);
        });

        // 3. Posicionar y mostrar el menú (cerca del cursor)
        const menuRect = {
            top: e.clientY - menu.offsetHeight / 2,
            left: e.clientX - menu.offsetWidth / 2
        };
        menu.style.display = 'block';
        menu.style.top = `${menuRect.top}px`;
        menu.style.left = `${menuRect.left}px`;

        // 4. Añadir manejo de eventos para cerrar el menú al hacer clic fuera
        document.addEventListener('click', handleOutsideClick);
    }

    // Función global para manejar clics fuera del menú y ocultarlo
    function handleOutsideClick(e) {
        const menu = document.getElementById('color-menu');
        if (menu && !menu.contains(e.target)) {
            menu.style.display = 'none';
            document.removeEventListener('click', handleOutsideClick); // Limpiar listener
        }
    }

    // 1. Evento de edición de contenido editable (focusout/keydown Enter)
    spreadsheet.addEventListener('focusout', handleCellEdit);
    spreadsheet.addEventListener('keydown', handleCellEdit); 

    // 2. Nuevo: Manejo del clic derecho para el menú contextual
    spreadsheet.addEventListener('contextmenu', handleContextMenu);
}
