function conectar() {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // Inicializar estilos si no existen (para que el estado sea consistente)
    if (!estado.styles) {
        estado.styles = {};
    }

    /**
     * Crea y muestra los controles de color sobre la celda seleccionada.
     * @param {HTMLElement} target - El elemento TD activo.
     */
    function showColorControls(target) {
        // 1. Limpiar cualquier control previo (si existe)
        const existingControls = document.getElementById('color-controls');
        if (existingControls) existingControls.remove();

        // 2. Crear el contenedor de controles y posicionarlo sobre la celda
        const controlsContainer = document.createElement('div');
        controlsContainer.id = 'color-controls';
        controlsContainer.className = 'cell-controls';

        // Usar data attributes para identificar qué celda estamos editando
        controlsContainer.dataset.col = target.dataset.col;
        controlsContainer.dataset.row = target.dataset.row;

        // 3. Crear el botón de color (el que abre el picker)
        const colorBtn = document.createElement('button');
        colorBtn.className = 'color-picker-btn';
        colorBtn.title = "Cambiar Color";

        // Inicializar el color visible del botón con lo guardado en estado
        const coordinate = `${target.dataset.col}${target.dataset.row}`;
        const currentColor = estado.styles[coordinate] || '#ffffff';
        colorBtn.style.backgroundColor = currentColor;
        colorBtn.style.backgroundImage = `radial-gradient(circle at center, ${currentColor} 50%, transparent 100%)`;


        // 4. Crear el input de color (para seleccionar un código hexadecimal)
        const colorInput = document.createElement('input');
        colorInput.type = 'color';
        colorInput.className = 'color-input';
        colorInput.value = currentColor;

        // Función que maneja la aplicación del color y el guardado de estado
        function applyColor(event) {
            let selectedColor;
            if (event.target.type === 'button' || event.target.closest('.cell-controls')) {
                // Si se hace clic en el botón, usamos el valor actual del input
                selectedColor = colorInput.value;
            } else {
                 // Si es un evento directo de cambio de color del picker (input type="color")
                selectedColor = event.target.value;
            }

            if (selectedColor) {
                const col = controlsContainer.dataset.col;
                const row = parseInt(controlsContainer.dataset.row);

                // Lógica: Actualizar el estado con el nuevo color.
                updateCellColorState(col, row, selectedColor);

                // 3. Guardar y Redibujar: persistir los datos y actualizar la UI.
                guardar();
                render();
            }
        }

        // Event Listeners para el control de color
        colorInput.addEventListener('input', (e) => {
             const col = controlsContainer.dataset.col;
             const row = parseInt(controlsContainer.dataset.row);
             updateCellColorState(col, row, e.target.value); // Actualiza en tiempo real mientras se selecciona

             // Opcional: Reflejar el cambio visualmente antes de perder foco
             render(); 
        });

        colorBtn.addEventListener('click', (e) => {
            // Simular un evento de input para disparar la lógica de aplicación de color
            const event = new Event('change');
            applyColor(event);
        });


        // Ensamblar el contenedor: Botón + Input
        controlsContainer.appendChild(colorBtn);
        controlsContainer.appendChild(colorInput);

        // 5. Inyectar los controles justo después del elemento TD activo (target)
        target.parentNode.insertBefore(controlsContainer, target.nextSibling);
    }


    /**
     * Manejador central para el contenido editable de las celdas.
     * Se adjunta un listener al contenedor principal (el <table>).
     * @param {Event} e - El evento disparado (focusout o keydown).
     */
    function handleCellEdit(e) {
        const target = e.target;

        // Verificar si el elemento objetivo es una celda editable y tiene las propiedades correctas
        if (!target || !target.hasAttribute('contenteditable') || !(target.dataset.col && target.dataset.row)) {
            return;
        }

        // Si se pierde el foco, limpiamos los controles visuales
        if (e.type === 'focusout' || e.type === 'blur') {
            const existingControls = document.getElementById('color-controls');
            if (existingControls) {
                existingControls.remove();
            }
            // Continuar con la lógica de guardar datos...
        }


        let newValue = '';
        let shouldUpdate = false;

        // 1. Determinar el nuevo valor basado en el evento:
        if (e.type === 'focusout' || e.type === 'blur') {
            newValue = target.textContent;
            shouldUpdate = true;

        } else if (e.type === 'keydown' && e.key === 'Enter') {
            newValue = target.textContent;
            shouldUpdate = true;
            e.preventDefault(); 
        } else if (e.type === 'focus') {
             // Mostrar controles al hacer foco
             showColorControls(target);
             return; // No procesar lógica de guardar/render hasta que haya un cambio real
        }
        else {
            return;
        }

        if (shouldUpdate && newValue !== undefined) {
            const col = target.dataset.col;
            const row = parseInt(target.dataset.row);

            // 2. Lógica: Actualizar el estado con el nuevo valor.
            updateCellState(col, row, newValue);

            // 3. Guardar y Redibujar: persistir los datos y actualizar la UI.
            guardar();
            render();
        }
    }


    // Usamos event delegation en el contenedor principal para capturar eventos de cualquier celda hija.
    spreadsheet.addEventListener('focusout', handleCellEdit);
    spreadsheet.addEventListener('blur', handleCellEdit); // Capturamos blur también por si acaso
    spreadsheet.addEventListener('keydown', handleCellEdit); 
}
