        if (e.type === 'focusout' || e.type === 'blur') {
            const existingControls = document.getElementById('color-controls');
            if (existingControls) {
                existingControls.remove();
            }
            // Si se pierde el foco, procesamos la lógica de guardar datos:
            let newValue = target.textContent;
            const col = target.dataset.col;
            const row = parseInt(target.dataset.row);

            if (newValue !== undefined) {
                updateCellState(col, row, newValue);
                guardar();
                render();
            }
            return; // Salir después de procesar el blur/focusout para evitar ejecutar la lógica de abajo
        }


        let newValue = '';
        let shouldUpdate = false;

        // Manejo de foco: mostrar controles y detener procesamiento normal
        if (e.type === 'focus') {
             showColorControls(target);
             return; 
        }

        // Manejo de Enter/keydown: procesar el valor y guardar
        if (e.type === 'keydown' && e.key === 'Enter') {
            newValue = target.textContent;
            shouldUpdate = true;
            e.preventDefault(); 
        } else {
            return; // Para otros eventos de keydown o tipos no manejados
        }

        if (shouldUpdate && newValue !== undefined) {
            const col = target.dataset.col;
            const row = parseInt(target.dataset.row);

            // 2. Lógica: Actualizar el estado con el nuevo valor.
            updateCellState(col, row, newValue);

            // 3. Guardar y Redibujar: persistir los datos y actualizar la UI.
            guardar();
            render();
        }
    }


    // Usamos event delegation en el contenedor principal para capturar eventos de cualquier celda hija.
    spreadsheet.addEventListener('focusout', handleCellEdit);
    spreadsheet.addEventListener('blur', handleCellEdit); // Capturamos blur también por si acaso
    spreadsheet.addEventListener('keydown', handleCellEdit); 
}
