### FUNCION: selectColumn
```js
function selectColumn(colChar) {
    const spreadsheet = document.getElementById('spreadsheet');
    const headers = spreadsheet.querySelectorAll('.col-header');
    const controlsPanel = document.getElementById('columnControlsPanel');
    const selectedColNameSpan = document.getElementById('selectedColName');

    // 1. Deseleccionar todos los encabezados
    headers.forEach(header => {
        header.classList.remove('selected');
    });

    // 2. Seleccionar el nuevo encabezado
    const selectedHeader = document.querySelector(`.col-header[data-col-char="${colChar}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
    }

    // 3. Actualizar estado y controles visibles
    estado.selectedColumn = colChar;
    guardar();
    render(); // Redibujar para aplicar cualquier estilo de selección si es necesario

    controlsPanel.classList.remove('hidden');
    selectedColNameSpan.textContent = colChar;
}
