function clearColumnContent() {
    const selectedCol = estado.selectedColumn;
    if (!selectedCol) return;

    // Iterar sobre todas las filas y borrar el contenido de la columna seleccionada en el estado
    for (let r = 1; r <= 20; r++) {
        const coordinate = getCoordinate(colToIndex(selectedCol), r);
        if (estado.data[coordinate]) {
            delete estado.data[coordinate];
        }
