### FUNCION: deleteColumn
```js
function deleteColumn() {
    const selectedCol = estado.selectedColumn;
    if (!selectedCol) return;

    // 1. Borrar todos los datos asociados a esta columna en el estado
    for (let r = 1; r <= 20; r++) {
        const coordinate = getCoordinate(colToIndex(selectedCol), r);
        delete estado.data[coordinate];
    }

    // 2. Limpiar estilos y selección de columna
    estado.columnStyles = Object.fromEntries(
        Object.entries(estado.columnStyles || {})
        .filter(([col, color]) => col !== selectedCol)
    );
    delete estado.selectedColumn;

    guardar();
    render(); // Redibujar la hoja para reflejar que la columna está vacía/borrada visualmente (aunque estructuralmente existe)
}
