### FUNCION: render
```js
function render() {
    const sheetBody = document.getElementById('spreadsheet').querySelector('tbody');
    if (!sheetBody) return;

    // 1. Limpiar cualquier clase de color de fondo existente antes de redibujar
    document.querySelectorAll('.td').forEach(td => {
        td.classList.remove('column-highlight-bg');
    });


    // Iterar sobre las 20 filas (1 a 20)
    for (let r = 1; r <= 20; r++) {
        // Obtener todas las celdas de la fila actual. Los hijos directos del tbody son los TRs.
        const rowElement = sheetBody.querySelectorAll(`[data-row="${r}"]`);
        if (!rowElement) continue;

        // Iterar sobre las 10 columnas (A a J) dentro de esa fila
        for (let cIndex = 0; cIndex < 10; cIndex++) {
            const colChar = getColChar(cIndex);
            const coordinate = getCoordinate(cIndex, r);

            // Encontrar el TD específico usando sus atributos data-col y data-row
            let cellElement = null;
            for (const td of rowElement) {
                if (td.getAttribute('data-col') === colChar) {
                    cellElement = td;
                    break;
                }
            }

            if (cellElement) {
                // Obtener el valor guardado en estado, si no existe, es una cadena vacía.
                const valueToShow = estado.data[coordinate] || "";

                // Establecer el contenido visible del elemento DOM.
                cellElement.textContent = valueToShow;

                // 2. Aplicar estilos de color y selección al renderizar
                if (estado.columnStyles && estado.columnStyles[colChar]) {
                    const color = estado.columnStyles[colChar];
                    cellElement.style.backgroundColor = color; // Usamos style directamente para asegurar la sobrescritura del CSS
                } else if (colChar === estado.selectedColumn) {
                     // Si no hay un color de fondo definido, pero está seleccionado, aplicar el resaltado visual
                     cellElement.classList.add('column-highlight-bg');
                }
            }
        }
    }

    // 3. Actualizar el estilo del encabezado de columna si hay selección activa
    const headers = document.querySelectorAll('.col-header');
     headers.forEach(header => {
        if (header.dataset.colChar === estado.selectedColumn) {
            header.classList.add('selected');
        } else {
            header.classList.remove('selected');
        }
    });
}
