### FUNCION: updateCellState
```js
/**
 * Actualiza el estado con un nuevo valor o estilo para una coordenada específica.
 * Esta función es puramente lógica y no interactúa con el DOM.
 * @param {string} col - La letra de la columna (A-J).
 * @param {number} row - El número de la fila (1-20).
 * @param {string | null} value - El nuevo texto a guardar, o null para borrar contenido.
 * @param {string | null} color - El nuevo color de fondo a aplicar, o null para no cambiarlo.
 */
function updateCellState(col, row, value = null, color = null) {
    const coordinate = getCoordinate(colToIndex(col), row);

    if (!estado.data[coordinate]) {
        // Inicializar el objeto de estado si es la primera vez que se toca esta celda
        estado.data[coordinate] = { value: "", backgroundColor: "" };
    }

    let state = estado.data[coordinate];

    // Actualizar valor
    state.value = String(value === null ? '' : value);

    // Actualizar color (si se proporcionó un nuevo color)
    if (color !== null) {
        state.backgroundColor = color;
    } else if (color === undefined && state.backgroundColor === "") {
         // Asegurarse que si no hay acción de color, el estado del color permanezca limpio o vacío
    }
}
