/**
 * Maneja las acciones de columna (borrar, colorear, etc.) después de seleccionar una columna.
 * @param {string} colChar - La letra de la columna activa.
 */
function handleColumnAction(colChar) {
    const action = document.getElementById('column-action-select').value;

    if (!action || !colChar) return;

    switch (action) {
        case 'clear':
            clearColumn(colChar);
            break;
        case 'color':
            // El valor del select debe contener el color elegido
            const selectedColor = document.getElementById('column-color-picker').value;
            if (selectedColor) {
                setColorColumn(colChar, selectedColor);
            }
            break;
    }

    // Después de la acción, limpiamos cualquier selección visual si es necesario
    document.querySelectorAll('.col-header').forEach(el => el.classList.remove('active'));
    const activeHeader = document.querySelector(`.col-header[data-char="${colChar}"]`);
    if (activeHeader) {
        activeHeader.classList.add('active');
    }
}
