### FUNCION: selectColumn
```js
/**
 * Selecciona una columna, actualiza el estado de selección y los controles.
 * @param {string} colChar - La letra de la columna (A-J).
 */
function selectColumn(colChar) {
    // 1. Actualizar estado global
    estado.selectedColumn = colChar;

    // 2. UI: Marcar visualmente la columna seleccionada en el encabezado
    const headerRow = document.querySelector('.col-header-row');
    if (headerRow) {
        Array.from(headerRow.querySelectorAll('.col-header')).forEach(th => {
            th.classList.remove('selected-column');
        });
        const selectedHeader = headerRow.querySelector(`.col-header[data-col="${colChar}"]`);
        if (selectedHeader) {
            selectedHeader.classList.add('selected-column');
        }
    }

    // 3. UI: Habilitar controles y actualizar el color picker con un valor por defecto si es necesario
    const controlsPanel = document.getElementById('controls-panel');
    document.getElementById('apply-color-btn').disabled = false;
    document.getElementById('clear-column-btn').disabled = false;

    // Opcional: Resetear el color picker o establecerlo a un valor predeterminado, por ejemplo rojo
    const colorPicker = document.getElementById('colorPicker');
    if (colorPicker) {
        colorPicker.value = '#ff0000'; // Default red for demonstration/reset
    }

    // 4. Redibujar para asegurar que cualquier estilo de selección se refleje
    render(); 
}
