### FUNCION: setColorByColumn
```js
/**
 * Aplica un color de fondo a todas las celdas de una columna específica.
 * NOTA: Esta función solo modifica el estilo visual (CSS) y no actualiza el estado.
 * @param {string} colChar - La letra de la columna a colorear.
 * @param {string} color - El código hexadecimal del color (#RRGGBB).
 */
function setColorByColumn(colChar, color) {
    // 1. Limpiar cualquier fondo anterior en esta columna primero
    const columnCells = document.querySelectorAll(`[data-col="${colChar}"]`);
    columnCells.forEach(cell => {
        cell.style.backgroundColor = ''; // Reset background
        cell.classList.remove('highlighted-cell');
    });

    // 2. Aplicar el nuevo color a todas las celdas de la columna
    columnCells.forEach(cell => {
        cell.style.backgroundColor = color;
        cell.classList.add('highlighted-cell');
    });
}
