### FUNCION: clearColumn
```js
/**
 * Borra el contenido de todas las celdas en una columna específica, actualizando el estado y la UI.
 * @param {string} colChar - La letra de la columna a vaciar.
 */
function clearColumn(colChar) {
    const sheetBody = document.querySelector('#spreadsheet tbody');
    if (!sheetBody || !colChar) return;

    let changed = false;
    // Iterar sobre las 20 filas (1 a 20) para borrar el contenido de cada celda.
    for (let r = 1; r <= 20; r++) {
        const coordinate = getCoordinate(colToIndex(colChar), r);
        if (estado.data[coordinate] !== "") {
            // Actualizar estado: vaciar la celda
            updateCellState(colChar, r, "");
            changed = true;
        }
    }

    if (changed) {
        guardar();
        render(); // Redibujar para que el contenido vacío se refleje en todos los TDs.
    }
}
