        } else if (e.type === 'keydown' && e.key === 'Enter') {
            // Se presionó Enter. Es equivalente a perder el foco y confirmar el valor.
            newValue = target.textContent;
            shouldUpdate = true;
            // Prevenir el comportamiento por defecto de Enter en un contenteditable
            e.preventDefault(); 

        } else {
            // Si es cualquier otro evento, ignorar o no hacer nada (ya que solo queremos focusout/Enter).
            return;
        }

        if (shouldUpdate && newValue !== undefined) {
            const col = target.dataset.col;
            const row = parseInt(target.dataset.row);

            // 2. Lógica: Actualizar el estado con el nuevo valor.
            updateCellState(col, row, newValue);

            // 3. Guardar y Redibujar: persistir los datos y actualizar la UI.
            guardar();
            render();
        }
    }

    // Usamos event delegation en el contenedor principal para capturar eventos de cualquier celda hija.
    spreadsheet.addEventListener('focusout', handleCellEdit);
    spreadsheet.addEventListener('keydown', handleCellEdit); 

    /**
     * Manejador global de keydown, específicamente para acciones en encabezados de columna.
     */
    function handleGlobalKeyDown(e) {
        // Solo actuar si el elemento activo está dentro o es un encabezado de columna
        const activeElement = document.activeElement;

        if (activeElement && activeElement.closest('.col-header')) {
            // Detectar la pulsación de Delete/Backspace cuando se selecciona una columna
            if (e.key === 'Delete' || e.key === 'Backspace') {
                const colHeader = activeElement.closest('.col-header');
                if (colHeader) {
                    const colChar = colHeader.textContent.trim();
                    // Evitar el comportamiento por defecto del navegador que podría interferir
                    e.preventDefault(); 
                    clearColumnState(colChar);
                }
            }
        }
    }

    // Escuchar eventos de teclado en todo el cuerpo para capturar la acción Delete/Backspace en los headers.
    document.body.addEventListener('keydown', handleGlobalKeyDown);
}
