function selectRow(rowIndex) {
    // 1. Actualizar estado
    estado.selectedRowId = rowIndex;

    // 2. Actualizar UI (mostrar/habilitar controles y mostrar el nombre de la fila)
    const controlsDiv = document.getElementById('row-controls');
    const displaySpan = document.getElementById('selected-row-display');

    if (controlsDiv && displaySpan) {
        controlsDiv.style.display = 'block';
        displaySpan.textContent = rowIndex;
    }

    // 3. Actualizar clases de selección visualmente en el DOM
    const rowContainer = document.getElementById('row-container');
    if (rowContainer && parseInt(rowContainer.dataset.row) === rowIndex) {
         // Solo si ya existe un contenedor con este ID, lo resaltamos. Mejor usar una clase general.
         let rowElement = document.querySelector(`.row-header[data-row="${rowIndex}"]`).closest('tr');
         if (rowElement) {
             rowElement.classList.add('selected-row');
         }
    }

    // Asegurarse de que cualquier fila previamente seleccionada pierda el estilo.
    document.querySelectorAll('.row-header').forEach(th => th.closest('tr') && th.closest('tr').classList.remove('selected-row'));
}
