### FUNCION: handleRowSelect
```js
function handleRowSelect(e) {
    // 1. Obtener el índice de la fila y manejar la selección visual
    const rowHeader = e.currentTarget;
    const rowIndex = parseInt(rowHeader.dataset.rowIndex);

    if (selectedRowIndex === rowIndex) {
        // Deseleccionar si ya estaba seleccionado
        selectRow(null);
        return;
    }

    // Limpiar selección anterior
    clearSelection();

    // Seleccionar la nueva fila
    selectRow(rowIndex);
}

function selectRow(rowIndex) {
    const rowHeaders = document.querySelectorAll('.row-header');
    if (rowHeaders.length === 0) return;

    let selectedElement = null;
    for (const header of rowHeaders) {
        header.classList.remove('selected-row');
        if (parseInt(header.dataset.rowIndex) === rowIndex) {
            header.classList.add('selected-row');
            selectedElement = header;
            break;
        }
    }

    // Actualizar estado y controles de la UI
    selectedRowIndex = rowIndex;
    document.getElementById('selected-row-display').textContent = `Selected Row: ${rowIndex}`;

    const deleteBtn = document.getElementById('delete-row-btn');
    const clearBtn = document.getElementById('clear-content-btn');

    if (rowIndex >= 1 && rowIndex <= 20) {
        deleteBtn.disabled = false;
        clearBtn.disabled = false;
    } else {
        deleteBtn.disabled = true;
        clearBtn.disabled = true;
    }
}

function clearSelection() {
    const rowHeaders = document.querySelectorAll('.row-header');
    for (const header of rowHeaders) {
        header.classList.remove('selected-row');
    }
    selectedRowIndex = null;
    document.getElementById('selected-row-display').textContent = 'No row selected';
    document.getElementById('delete-row-btn').disabled = true;
    document.getElementById('clear-content-btn').disabled = true;
}
