function deleteSelectedRow() {
    if (selectedRowIndex === null) return;

    const rowElement = document.querySelector(`[data-row="${selectedRowIndex}"]`);
    if (!rowElement) return;

    // 1. Limpiar el estado de la selección
    clearSelection();

    // 2. Eliminar los datos asociados a esta fila en 'estado.data'
    const cells = rowElement.querySelectorAll('[contenteditable="true"]');
