### FUNCION: deleteSelectedRow
```javascript
function deleteSelectedRow() {
    if (estado.selectedRowIndex === null) return;

    const rowIndex = estado.selectedRowIndex;

    // 1. Preguntar al usuario si realmente desea borrar la fila
    if (!confirm(`¿Está seguro de que desea eliminar completamente la Fila ${rowIndex}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 2. Limpiar el estado: Eliminar todas las coordenadas de esta fila
    const keysToDelete = Object.keys(estado.data).filter(key => key.endsWith(`${rowIndex}`));
    for (const key of keysToDelete) {
        delete estado.data[key];
    }

    // 3. Limpiar el DOM: Eliminar todas las celdas y el header de esta fila
    const rowCells = document.querySelectorAll(`[data-row="${rowIndex}"]`);
    const rowHeader = document.querySelector('.row-header');

    if (rowCells) {
        rowCells.forEach(cell => cell.remove());
    }
    if (rowHeader && rowHeader.parentNode) {
        rowHeader.parentNode.removeChild(rowHeader);
    }

    // 4. Resetear el estado de selección y actualizar la vista
    estado.selectedRowIndex = null;
    render(); // Redibujar para asegurar que la UI está limpia
    guardar();
}
