### ARCHIVO: script.js
```javascript
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====

/**
 * Estado global para almacenar los datos de la hoja de cálculo.
 * La estructura es un objeto donde las claves son las coordenadas (ej: "A1", "J20")
 * y los valores son el texto contenido en esa celda.
 */
let estado = {
    data: {},
    selectedRowIndex: null // NUEVO ESTADO: Almacena el número de la fila seleccionada (1-20)
};
const CLAVE = "app";

/**
 * Carga el estado desde localStorage si existe.
 */
function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) 
            estado = JSON.parse(s); 
    } catch (e) {
        console.error("Error al cargar el estado:", e);
    }
}

/**
 * Guarda el estado actual en localStorage.
 */
function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) {
        console.error("Error al guardar el estado:", e);
    }
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Convierte un índice de columna (0-9) en su letra correspondiente (A-J).
 * @param {number} index - El índice de columna (0=A, 1=B, etc.)
 * @returns {string} La letra de la columna.
 */
function getColChar(index) {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    return alphabet[index].toUpperCase();
}

/**
 * Genera una clave de coordenada (ej: "A1", "J20").
 * @param {number} colIndex - Índice de la columna (0-9).
 * @param {number} rowIndex - Número de la fila (1-20).
 * @returns {string} La clave de la celda.
 */
function getCoordinate(colIndex, rowIndex) {
    return getColChar(colIndex) + rowIndex;
}

/**
 * Actualiza el estado con un nuevo valor para una coordenada específica.
 * Esta función es puramente lógica y no interactúa con el DOM.
 * @param {string} col - La letra de la columna (A-J).
 * @param {number} row - El número de la fila (1-20).
 * @param {string} value - El nuevo texto a guardar.
 */
function updateCellState(col, row, value) {
    const coordinate = getCoordinate(colToIndex(col), row);
    estado.data[coordinate] = String(value || '');
}

/**
 * Helper para convertir letras de columna (A-J) a índices numéricos (0-9).
 * @param {string} colChar - La letra de la columna.
 * @returns {number} El índice numérico (0-9).
 */
function colToIndex(colChar) {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    return alphabet.indexOf(colChar);
}

/** 
 * Selecciona una fila y actualiza el estado de selección visual.
 * @param {number} rowIndex - El número de la fila a seleccionar (1-20).
 */
function selectRow(rowIndex) {
    if (estado.selectedRowIndex === rowIndex) return;

    // 1. Deseleccionar la fila anterior
    const oldSelected = estado.selectedRowIndex;
    if (oldSelected !== null) {
        // Eliminar cualquier clase de selección visual previa
        document.querySelectorAll(`[data-row="${oldSelected}"]`).forEach(el => {
            el.classList.remove('selected-row');
        });
    }

    // 2. Actualizar el estado y seleccionar la nueva fila
    estado.selectedRowIndex = rowIndex;
    console.log(`Fila ${rowIndex} seleccionada.`);

    // 3. Aplicar clase visual a los elementos DOM de la fila seleccionada (headers)
    const rowHeaders = document.querySelectorAll('.row-header');
    if (rowHeaders[rowIndex - 1]) { // Los headers están en orden, índice 0 es para Fila 1
        rowHeaders[rowIndex - 1].classList.add('selected-row');
    }

    // Aplicar clase a todas las celdas de la fila seleccionada
    const cells = document.querySelectorAll(`[data-row="${rowIndex}"]`);
    cells.forEach(cell => {
        cell.classList.add('selected-row');
    });
}


/** 
 * Borra el contenido de todas las celdas de la fila actualmente seleccionada.
 */
function clearSelectedRowContent() {
    if (estado.selectedRowIndex === null) return;

    const rowIndex = estado.selectedRowIndex;
    let updatedCount = 0;

    // Iterar sobre las 10 columnas y vaciar el contenido en el estado y en el DOM
    for (let cIndex = 0; cIndex < 10; cIndex++) {
        const colChar = getColChar(cIndex);
        const coordinate = getCoordinate(cIndex, rowIndex);

        // Actualizar lógica: limpiar estado
        updateCellState(colChar, rowIndex, '');

        // Actualizar DOM: vaciar la celda visible
        const cellElement = document.querySelector(`[data-col="${colChar}"][data-row="${rowIndex}"]`);
        if (cellElement) {
            cellElement.textContent = '';
            updatedCount++;
        }
    }

    // Guardar y redibujar para reflejar los cambios en el estado global
    guardar();
    render();
}


/** 
 * Elimina completamente la fila seleccionada (datos y estructura visible).
 */
function deleteSelectedRow() {
    if (estado.selectedRowIndex === null) return;

    const rowIndex = estado.selectedRowIndex;

    // 1. Preguntar al usuario si realmente desea borrar la fila
    if (!confirm(`¿Está seguro de que desea eliminar completamente la Fila ${rowIndex}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 2. Limpiar el estado: Eliminar todas las coordenadas de esta fila
    const keysToDelete = Object.keys(estado.data).filter(key => key.endsWith(`${rowIndex}`));
    for (const key of keysToDelete) {
        delete estado.data[key];
    }

    // 3. Limpiar el DOM: Eliminar todas las celdas y el header de esta fila
    const rowCells = document.querySelectorAll(`[data-row="${rowIndex}"]`);
    const rowHeader = document.querySelector('.row-header');

    if (rowCells) {
        rowCells.forEach(cell => cell.remove());
    }
    // El header está en la primera fila de <tr> dentro del tbody, por lo que usamos su clase y el índice.
    const allRows = document.querySelectorAll('#sheet-body > tr');
    if (allRows[rowIndex - 1]) {
        allRows[rowIndex - 1].remove();
    }


    // 4. Resetear el estado de selección y actualizar la vista
    estado.selectedRowIndex = null;
    render(); // Redibujar para asegurar que la UI está limpia
    guardar();
}

/** 
 * Aplica un color de fondo a todas las celdas de la fila seleccionada (solo visual).
 * @param {string} color - El código de color CSS.
 */
function colorSelectedRow(color) {
    if (estado.selectedRowIndex === null) return;

    const rowIndex = estado.selectedRowIndex;

    // 1. Aplicar el estilo de fondo a todas las celdas de la fila seleccionada
    document.querySelectorAll(`[data-row="${rowIndex}"]`).forEach(cell => {
        cell.style.backgroundColor = color;
    });
}


/**
 * Muestra un menú contextual (popover) con acciones disponibles para la fila seleccionada.
 * @param {Event} e - Evento de contexto.
 * @param {number} rowIndex - Índice de la fila seleccionada.
 */
function showContextMenu(e, rowIndex) {
    const menu = document.getElementById('context-menu');
    if (!menu) return;

    // Limpiar contenido previo
    Array.from(menu.querySelectorAll('button')).forEach(btn => btn.remove());

    // Crear botones de acción
    const actions = [
        { text: 'Borrar Fila', action: deleteSelectedRow, class: '' },
        { text: 'Vaciar Contenido', action: clearSelectedRowContent, class: '' },
        { text: 'Color de Fondo...', action: () => promptColor(e) } // Acción que requiere input
    ];

    actions.forEach(action => {
        const button = document.createElement('button');
        button.textContent = action.text;
        // Attach handler to the button
        button.onclick = function() {
            if (action.action) {
                // Ejecutar la acción y ocultar el menú después de la ejecución
                action.action();
            }
            menu.style.display = 'none';
        };
        menu.appendChild(button);
    });

    // Posicionar el menú en las coordenadas del evento
    menu.style.left = `${e.pageX}px`;
    menu.style.top = `${e.pageY}px`;
    menu.style.display = 'block';
}

/** 
 * Solicita un color al usuario y llama a la función de coloreado.
 * @param {Event} e - Evento original (para prevenir el menú).
 */
function promptColor(e) {
    const color = prompt("Ingrese un código de color CSS (ej: #ff0000 o blue):");
    if (color && color !== 'null') {
        // Ocultar el menú antes de ejecutar la acción
        document.getElementById('context-menu').style.display = 'none';
        colorSelectedRow(color);
    }
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const sheetBody = document.getElementById('sheet-body'); // Cambiado ID por el nuevo <tbody>
    if (!sheetBody) return;

    // Limpiar contenido para asegurar un re-render limpio antes de volver a dibujar
    sheetBody.innerHTML = ''; 
    let currentFragment = document.createDocumentFragment();


    // Iterar sobre las 20 filas (1 a 20)
    for (let r = 1; r <= 20; r++) {
        const rowElement = document.createElement('tr');
        rowElement.dataset.row = r;

        // Añadir el header de fila (#)
        const rowHeaderCell = document.createElement('th');
        rowHeaderCell.className = 'row-header';
        rowHeaderCell.textContent = r;
        rowHeaderCell.style.cursor = 'pointer'; // Indica que es clickable

        // Añadir las 10 celdas de datos (A a J)
        for (let cIndex = 0; cIndex < 10; cIndex++) {
            const colChar = getColChar(cIndex);
            const coordinate = getCoordinate(cIndex, r);

            const td = document.createElement('td');
            td.className = 'cell-data'; // Clase para estilo general de celda
            td.setAttribute('contenteditable', 'true');
            td.dataset.col = colChar;
            td.dataset.row = r;

            // Establecer el valor visible del elemento DOM (si está en estado)
            const valueToShow = estado.data[coordinate] || "";
            td.textContent = valueToShow;

            // Añadir un listener de blur/focusout para que la lógica detecte cambios al salir de la celda
            td.addEventListener('blur', handleCellEdit); 
            td.addEventListener('keydown', handleCellEdit);

            rowElement.appendChild(td);
        }

        // Agregar el header de fila y luego las celdas (manteniendo la estructura correcta)
        rowElement.prepend(rowHeaderCell);
        currentFragment.appendChild(rowElement);
    }
    sheetBody.appendChild(currentFragment);

    // Después de recrear todo, re-adjuntamos el listener de click para selección de filas
    document.getElementById('spreadsheet').removeEventListener('click', handleCellClickWrapper); // Evitar duplicación
    document.getElementById('spreadsheet').addEventListener('click', handleCellClickWrapper); 
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // --- WRAPPER PARA MANEJAR EVENTOS DE CLIC EN LA SELECCIÓN DE FILA Y EL CONTEXTO MENU ---

    /**
     * Manejador de clics en el contenedor principal para detectar la selección de filas.
     */
    function handleCellClickWrapper(e) {
        const target = e.target;
        // Si se hace clic directamente en un header, lo seleccionamos.
        if (target.classList.contains('row-header')) {
            const rowIndex = parseInt(target.textContent);
            selectRow(rowIndex);
        } 
    }

    /**
     * Manejador central para el contenido editable de las celdas.
     * Se adjunta un listener al contenedor principal (el <table>).
     */
    function handleCellEdit(e) {
        const target = e.target;

        // Verificar si el elemento objetivo es una celda editable y tiene las propiedades correctas
        if (!target || !target.hasAttribute('contenteditable') || !(target.dataset.col && target.dataset.row)) {
            return;
        }

        let newValue = '';
        let shouldUpdate = false;

        // 1. Determinar el nuevo valor basado en el evento:
        if (e.type === 'focusout' || e.type === 'blur') {
            // Se perdió el foco. El contenido visible es el valor a guardar.
            newValue = target.textContent;
            shouldUpdate = true;

        } else if (e.type === 'keydown' && e.key === 'Enter') {
            // Se presionó Enter. Es equivalente a perder el foco y confirmar el valor.
            newValue = target.textContent;
            shouldUpdate = true;
            // Prevenir el comportamiento por defecto de Enter en un contenteditable
            e.preventDefault(); 

        } else {
            // Si es cualquier otro evento, ignorar o no hacer nada (ya que solo queremos focusout/Enter).
            return;
        }

        if (shouldUpdate && newValue !== undefined) {
            const col = target.dataset.col;
            const row = parseInt(target.dataset.row);

            // 2. Lógica: Actualizar el estado con el nuevo valor.
            updateCellState(col, row, newValue);

            // 3. Guardar y Redibujar: persistir los datos y actualizar la UI.
            guardar();
            render();
        }
    }

