function selectRow(rowIndex) {
    // 1. Limpiar la selección anterior
    const sheetBody = document.getElementById('spreadsheet').querySelector('tbody');
    if (sheetBody) {
        Array.from(sheetBody.querySelectorAll('.row-header')).forEach(el => {
            el.classList.remove('selected-row');
        });
    }

    // 2. Actualizar el estado de la fila seleccionada
