        const rowElement = document.querySelector(`.row-header[data-row-num="${rowIndex}"]`).closest('tr');
        if (rowElement) {
            rowElement.remove();
        }
    }

    // Nota: Aquí se asume que la eliminación no requiere reindexar todas las filas, 
