 */
function updateControlStates() {
    const isRowSelected = estado.selectedRowIndex !== null;
    document.getElementById('selectRowButton').disabled = true; // Siempre deshabilitado después del primer clic

    const clearBtn = document.getElementById('clearRowBtn');
    const colorBtn = document.getElementById('colorRowBtn');
    const deleteBtn = document.getElementById('deleteRowBtn');

    if (isRowSelected) {
        clearBtn.disabled = false;
        colorBtn.disabled = false;
        deleteBtn.disabled = false;
    } else {
        clearBtn.disabled = true;
        colorBtn.disabled = true;
        deleteBtn.disabled = true;
    }
}

/**
 * Borra el contenido de todas las celdas en la fila actualmente seleccionada, actualizando el estado.
 */
function clearSelectedRow() {
    const rowIndex = estado.selectedRowIndex;
    if (rowIndex === null) return;

    // Iterar sobre todas las 10 columnas (A a J)
    for (let cIndex = 0; cIndex < 10; cIndex++) {
        const colChar = getColChar(cIndex);
        const coordinate = getCoordinate(cIndex, rowIndex);

        // Actualizar el estado para vaciar la celda.
        updateCellState(colChar, rowIndex, '');
    }

    console.log(`Fila ${rowIndex} vaciada.`);
    guardar();
    render();
}

/**
 * Elimina completamente los datos de una fila del estado y limpia el DOM (simulando la eliminación).
 */
function deleteSelectedRow() {
    const rowIndex = estado.selectedRowIndex;
    if (rowIndex === null) return;

    // 1. Limpiar el estado para todas las coordenadas de esa fila
    for (let cIndex = 0; cIndex < 10; cIndex++) {
        const colChar = getColChar(cIndex);
        const coordinate = getCoordinate(cIndex, rowIndex);
        delete estado.data[coordinate];
    }

    // 2. Eliminar la fila del DOM (esto es crucial para que el render funcione bien)
    const rowElement = document.querySelector(`tbody tr[data-row="${rowIndex}"]`);
    if (rowElement) {
        rowElement.remove();
    }

    // 3. Resetear estado y UI
    estado.selectedRowIndex = null;
    console.log(`Fila ${rowIndex} eliminada.`);
    updateControlStates();
    guardar();
    render(); // Re-render para asegurar la consistencia visual (aunque el DOM se haya modificado)
}

/**
 * Aplica un color de fondo a todas las celdas de la fila seleccionada.
 */
function colorizeSelectedRow() {
    const rowIndex = estado.selectedRowIndex;
    if (rowIndex === null) return;

    // 1. Limpiar colores anteriores en toda la fila
    document.querySelectorAll(`[data-row="${rowIndex}"]`).forEach(cell => {
        cell.style.backgroundColor = ''; // Resetear color
        cell.removeAttribute('data-color');
    });

    // 2. Aplicar el nuevo color (ejemplo: amarillo claro)
    const color = '#fffacd'; // LemonChiffon
    document.querySelectorAll(`[data-row="${rowIndex}"]`).forEach(cell => {
        cell.style.backgroundColor = color;
        cell.setAttribute('data-color', 'true');
    });

    console.log(`Fila ${rowIndex} coloreada.`);
    // Nota: Si el color debe guardarse en estado, se haría aquí. Por ahora solo es visual.
    guardar(); 
    render(); 
}
