function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            const loadedState = JSON.parse(s);
            estado.data = loadedState.data || {};
            // Reconstruir Sets a partir de arrays guardados
            estado.hiddenCols = new Set(loadedState.hiddenCols ? loadedState.hiddenCols : []);
            estado.hiddenRows = new Set(loadedState.hiddenRows ? loadedState.hiddenRows : []);
        } else {
             // Inicializar estados por defecto si no hay nada guardado
            estado.hiddenCols = new Set(); // Ninguna columna oculta inicialmente
            estado.hiddenRows = new Set(); // Ninguna fila oculta inicialmente
        }
    } catch (e) {
        console.error("Error al cargar el estado:", e);
    }
}
