function guardar() { 
    try { 
        // Convertir Sets a Arrays para serialización JSON
        const serializableState = {
            data: estado.data,
            hiddenCols: Array.from(estado.hiddenCols),
            hiddenRows: Array.from(estado.hiddenRows)
        };
        localStorage.setItem(CLAVE, JSON.stringify(serializableState)); 
    } catch (e) {
        console.error("Error al guardar el estado:", e);
    }
}
