function render() {
    const sheetBody = document.getElementById('spreadsheet').querySelector('tbody');
    if (!sheetBody) return;

    // 1. Limpiar y re-dibujar los elementos de la cabecera (Column Headers)
    const headerRow = document.getElementById('spreadsheet').querySelector('thead tr');
    if (headerRow) {
        Array.from(headerRow.children).forEach((th, index) => {
            const colIndex = parseInt(th.getAttribute('data-col-index'));
            const isHidden = estado.hiddenCols.has(colIndex);

            if (isHidden && !th.classList.contains('hidden')) {
                th.classList.add('hidden');
            } else if (!isHidden && th.classList.contains('hidden')) {
                th.classList.remove('hidden');
            }
        });
    }


    // 2. Iterar sobre las filas (1 a 20)
    for (let r = 1; r <= 20; r++) {
        const isRowHidden = estado.hiddenRows.has(r);

        // Obtener todas las celdas de la fila actual. Los hijos directos del tbody son los TRs.
        const rowElement = sheetBody.querySelectorAll(`[data-row="${r}"]`);
        if (!rowElement) continue;

        // Aplicar visibilidad a toda la fila si está oculta
        if (isRowHidden) {
            rowElement.forEach(el => el.style.display = 'none');
            continue; 
        } else {
             rowElement.forEach(el => el.style.display = ''); // Asegurar que se muestren si no están ocultas
        }


        // Iterar sobre las columnas (A a J) dentro de esa fila
        for (let cIndex = 0; cIndex < 10; cIndex++) {
            const colChar = getColChar(cIndex);
            const coordinate = getCoordinate(cIndex, r);

            // Aplicar visibilidad al encabezado de columna A-J en la cabecera (thead)
            let thHeader = document.querySelector(`th[data-col="${colChar}"]`);
            if (thHeader) {
                 const isColHidden = estado.hiddenCols.has(cIndex);
                 if (isColHidden && !thHeader.classList.contains('hidden')) {
                    thHeader.classList.add('hidden');
                } else if (!isColHidden && thHeader.classList.contains('hidden')) {
                    thHeader.classList.remove('hidden');
                }
            }


            // Encontrar el TD específico usando sus atributos data-col y data-row
            let cellElement = null;
            for (const td of rowElement) {
                if (td.getAttribute('data-col') === colChar) {
                    cellElement = td;
                    break;
                }
            }

            if (cellElement) {
                // Aplicar visibilidad a la celda de datos si su columna está oculta o la fila está oculta
                const isColHidden = estado.hiddenCols.has(cIndex);
                const isRowVisible = !isRowHidden; // Solo necesitamos comprobar si el TR ya se manejó arriba

                if (!isColHidden && isRowVisible) {
                    // Obtener el valor guardado en estado, si no existe, es una cadena vacía.
                    const valueToShow = estado.data[coordinate] || "";

                    // Establecer el contenido visible del elemento DOM.
                    cellElement.textContent = valueToShow;
                    cellElement.style.display = ''; // Asegurar visibilidad de la celda de datos si se pasó la prueba inicial
                } else {
                    cellElement.textContent = '';
                    cellElement.style.display = 'none'; 
                }
            }
        }
    }
}

