            return;
        }

        if (shouldUpdate && newValue !== undefined) {
            const col = target.dataset.col;
            const row = parseInt(target.dataset.row);

            // 2. Lógica: Actualizar el estado con el nuevo valor.
            updateCellState(col, row, newValue);

            // 3. Guardar y Redibujar: persistir los datos y actualizar la UI.
            guardar();
            render();
        }
    }


     /**
     * Manejador de contexto para cabeceras (Column/Row Headers).
     */
    function handleContextMenu(e) {
        // Prevenir el menú contextual nativo del navegador
        e.preventDefault();

        const target = e.target;

        if (target.classList.contains('col-header')) {
            const colIndex = parseInt(target.dataset.colIndex);
            // Mostrar un menú simple para ocultar/mostrar columna
            showContextMenu(e, 'column', colIndex);
        } else if (target.classList.contains('row-header')) {
            const rowIndex = parseInt(target.getAttribute('data-row'));
             // Mostrar un menú simple para ocultar/mostrar fila
            showContextMenu(e, 'row', rowIndex);
        }
    }

     /**
      * Muestra un menú contextual simulado en la posición del evento.
      */
    function showContextMenu(event, type, index) {
        // Crear el contenedor de menú (simulando un popover/tooltip por simplicidad)
        let menu = document.getElementById('context-menu');
        if (!menu) {
            menu = document.createElement('div');
            menu.id = 'context-menu';
            menu.style.position = 'absolute';
            menu.style.background = 'white';
            menu.style.border = '1px solid #ccc';
            menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
            menu.style.zIndex = '1000';
            document.body.appendChild(menu);
        }

        // Limpiar contenido previo
        menu.innerHTML = '';

        const hideButton = document.createElement('button');
        hideButton.textContent = `Ocultar ${type === 'column' ? 'columna' : 'fila'} ${index}`;
        hideButton.onclick = () => {
            if (type === 'column') {
                hideColumn(index);
            } else {
                hideRow(index);
            }
            guardar();
            render();
            menu.style.display = 'none';
        };

        const showButton = document.createElement('button');
        showButton.textContent = `Mostrar ${type === 'column' ? 'columna' : 'fila'} ${index}`;
        showButton.onclick = () => {
             if (type === 'column') {
                unhideColumn(index);
            } else {
                unhideRow(index);
            }
            guardar();
            render();
            menu.style.display = 'none';
        };

        // Estilos básicos para el menú en línea (se añadiría mejor en CSS, pero aquí para asegurar funcionalidad)
        const styleSheet = document.createElement("style");
        styleSheet.type = "text/css";
        styleSheet.innerText = `#context-menu button { display: block; width: 100%; padding: 5px; border: none; background: #eee; cursor: pointer; }`;
        document.head.appendChild(styleSheet);


        // Construir el menú
        const contentDiv = document.createElement('div');
        contentDiv.appendChild(hideButton);
        contentDiv.appendChild(showButton);
        menu.appendChild(contentDiv);

        // Posicionar y mostrar el menú
        menu.style.left = `${event.clientX + 5}px`;
        menu.style.top = `${event.clientY + 5}px`;
        menu.style.display = 'block';
    }


