function render() {
    const sheetBody = document.getElementById('spreadsheet').querySelector('tbody');
    if (!sheetBody) return;

    // --- Renderizar Encabezados de Columna (Thead) ---
    const headerCells = document.getElementById('spreadsheet').querySelectorAll('.col-header');
    for (let cIndex = 0; cIndex < 10; cIndex++) {
        const colChar = getColChar(cIndex);
        if (!estado.visibleCols.has(colChar)) {
            // Ocultar la cabecera de columna si no es visible en el estado
            headerCells[cIndex].style.display = 'none';
        } else {
            headerCells[cIndex].style.display = ''; // Mostrarla
        }
    }

    // Iterar sobre las 20 filas (1 a 20)
    for (let r = 1; r <= 20; r++) {
        if (!estado.visibleRows.has(r)) continue; // Saltar si la fila está oculta

        const rowElement = sheetBody.querySelectorAll(`[data-row="${r}"]`);
        if (!rowElement) continue;

        // Iterar sobre las 10 columnas (A a J) dentro de esa fila
        for (let cIndex = 0; cIndex < 10; cIndex++) {
            const colChar = getColChar(cIndex);
            const coordinate = getCoordinate(cIndex, r);

            // Solo renderizar si la columna es visible Y la fila ya fue chequeada arriba.
            if (!estado.visibleCols.has(colChar)) continue; 

            let cellElement = null;
            for (const td of rowElement) {
                if (td.getAttribute('data-col') === colChar && parseInt(td.dataset.row) === r) {
                    cellElement = td;
                    break;
                }
            }

            if (cellElement) {
                // Obtener el valor guardado en estado, si no existe, es una cadena vacía.
                const valueToShow = estado.data[coordinate] || "";

                // Establecer el contenido visible del elemento DOM.
                cellElement.textContent = valueToShow;
            }
        }
    }
}
