<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Spreadsheet App</title>
    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <h1>Interactive Spreadsheet</h1>

    <table id="spreadsheet">
        <thead>
            <tr id="header-row">
                <!-- Empty corner cell -->
                <th></th > 
                <!-- Column Headers A to J -->
                <th class="col-header" data-char="A">A</th>
                <th class="col-header" data-char="B">B</th>
                <th class="col-header" data-char="C">C</th>
                <th class="col-header" data-char="D">D</th>
                <th class="col-header" data-char="E">E</th>
                <th class="col-header" data-char="F">F</th>
                <th class="col-header" data-char="G">G</th>
                <th class="col-header" data-char="H">H</th>
                <th class="col-header" data-char="I">I</th>
                <th class="col-header" data-char="J">J</th>
            </tr >
        </thead>
        <tbody id="spreadsheet-body">
            <!-- Rows 1 to 20 -->
            <tr data-row="1">
                <th class="row-header">1</th>
                <td contenteditable="true" data-col="A" data-row="1"></td >
                <td contenteditable="true" data-col="B" data-row="1"></td >
                <td contenteditable="true" data-col="C" data-row="1"></td >
                <td contenteditable="true" data-col="D" data-row="1"></td >
                <td contenteditable="true" data-col="E" data-row="1"></td >
                <td contenteditable="true" data-col="F" data-row="1"></td >
                <td contenteditable="true" data-col="G" data-row="1"></td >
                <td contenteditable="true" data-col="H" data-row="1"></td >
                <td contenteditable="true" data-col="I" data-row="1"></td >
                <td contenteditable="true" data-col="J" data-row="1"></td >
            </tr>
            <!-- RESUMIDO por el harness: acá van 18 repeticiones más, iguales a la de arriba y la de abajo (solo cambian los números) -->
            <tr data-row="20">
                <th class="row-header">20</th>
                <td contenteditable="true" data-col="A" data-row="20"></td >
                <td contenteditable="true" data-col="B" data-row="20"></td >
                <td contenteditable="true" data-col="C" data-row="20"></td >
                <td contenteditable="true" data-col="D" data-row="20"></td >
                <td contenteditable="true" data-col="E" data-row="20"></td >
                <td contenteditable="true" data-col="F" data-row="20"></td >
                <td contenteditable="true" data-col="G" data-row="20"></td >
                <td contenteditable="true" data-col="H" data-row="20"></td >
                <td contenteditable="true" data-col="I" data-row="20"></td >
                <td contenteditable="true" data-col="J" data-row="20"></td >
            </tr>
        </tbody>
    </table>

    <script src="script.js"></script>
</body>
</html>
